/** Shared social preview image (generated by app/opengraph-image.tsx). Pages that set their own
 *  openGraph object must pass this again, because Next.js replaces the whole openGraph object. */
export const ogImage = { url: "/opengraph-image", width: 1200, height: 630, alt: "Umair Sadiq, WordPress developer and SEO specialist" };

/** Trim text for a meta description at a word boundary. */
export function clip(text: string, max = 155) {
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  return `${cut.slice(0, cut.lastIndexOf(" "))}…`;
}
